H, W = 19, 16
bg = 4

# Final algorithm-generated output
output = [[bg] * W for _ in range(H)]

# Original positions
original_1s = [(2, 2), (4, 14), (10, 10), (17, 9)]
original_6s = [(4, 4), (6, 6), (7, 14), (15, 2)]

def is_diagonal(r1, c1, r2, c2):
    return abs(r1 - r2) == abs(c1 - c2)

def get_diag_pairs(cells):
    pairs = []
    for i, (r1, c1) in enumerate(cells):
        for j, (r2, c2) in enumerate(cells):
            if i < j and is_diagonal(r1, c1, r2, c2):
                pairs.append(((r1, c1), (r2, c2)))
    return pairs

